    seoTitle: 'Build de PC para LLM local por menos de $1,000 con GPU usada (2026)',
    intro: '**Una PC con una RTX 3060 12GB usada, un Ryzen 5 7600 y 32GB de RAM DDR5 ejecuta modelos de 7B a 14B en Q4 y suma unos $910, menos de $1,000.** La VRAM es el principal factor limitante para la inferencia de LLM local, así que este build destina su presupuesto de GPU a una tarjeta con 12GB de VRAM a un precio de segunda mano de unos $300 (del [rastreador de InsiderLLM](https://insiderllm.com/guides/nvidia-gpu-prices-rising/), fuente actualizada el 2026-10-15) y mantiene modestos los demás componentes. Un modelo de 14B en Q4 (unos 9-10GB) cabe en 12GB; los modelos de clase 32B no caben por completo y requieren descargar capas a la CPU, lo cual es mucho más lento. Esta guía detalla los componentes exactos, por qué se eligió cada uno frente a las alternativas y qué cifras de velocidad tienen fuente. El resto de piezas son estimaciones propias de esta página, y el total solo se cumple con una tarjeta usada: una RTX 3060 12GB nueva, listada en unos $450 en [gpuprix](https://gpuprix.com/us/gpus/geforce-rtx-3060-12gb) (2026-11-18), lo llevaría a unos $1,060.',
