    leadAnswerBlock: '**Una PC para LLM local por menos de $1,000 se centra en un solo componente: la GPU, elegida por VRAM por dólar. Una RTX 3060 12GB usada (unos $300, rastreador de InsiderLLM) combinada con un Ryzen 5 7600 ($180), 32GB de DDR5-6000 ($90), un SSD NVMe Gen4 de 1TB ($70), una placa base B650 mATX ($130), una fuente 650W 80+ Gold ($75) y un gabinete mATX ($65) suma unos $910. Ejecuta modelos de 7B a 14B en Q4; la única velocidad con fuente para esta GPU es 75.6 tok/s con Llama 2 7B Q4_0 (discusión #15013 de llama.cpp, reportada por la comunidad, no medida por PromptQuorum). Los modelos de clase 32B no caben por completo en 12GB.**',
