    seoTitle: '중고 GPU로 $1,000 미만 로컬 LLM PC 빌드(2026)',
    intro: '**중고 RTX 3060 12GB, Ryzen 5 7600, 32GB DDR5 RAM을 탑재한 PC는 7B~14B 모델을 Q4에서 실행하며 총비용은 약 $910으로 $1,000 미만입니다.** VRAM은 로컬 LLM 추론의 주된 제약 요소이므로, 이 빌드는 GPU 예산을 중고가 약 $300인 12GB VRAM 카드에 사용하고([InsiderLLM 트래커](https://insiderllm.com/guides/nvidia-gpu-prices-rising/), 출처 갱신일 2026-10-15) 나머지 부품은 소박하게 구성합니다. Q4의 14B 모델(약 9-10GB)은 12GB에 들어가지만, 32B급 모델은 완전히 들어가지 않아 CPU로 일부를 오프로드해야 하며 속도가 크게 느려집니다. 이 가이드는 정확한 부품 구성, 각 부품을 대안보다 선택한 이유, 그리고 출처가 있는 속도 수치를 안내합니다. 나머지 부품은 이 페이지의 자체 추정치이며, 총액은 중고 카드일 때만 성립합니다. 2026-11-18 기준 [gpuprix](https://gpuprix.com/us/gpus/geforce-rtx-3060-12gb)에 약 $450으로 등록된 새 RTX 3060 12GB를 선택하면 총액은 약 $1,060이 됩니다.',
