    leadAnswerBlock: '**$1,000 미만 로컬 LLM PC 빌드는 하나의 부품, 즉 달러당 VRAM을 기준으로 고른 GPU에 집중합니다. 중고 RTX 3060 12GB(약 $300, InsiderLLM 트래커)에 Ryzen 5 7600($180), 32GB DDR5-6000($90), 1TB Gen4 NVMe SSD($70), B650 mATX 보드($130), 650W 80+ Gold PSU($75), mATX 케이스($65)를 합치면 총 약 $910입니다. 7B~14B 모델을 Q4에서 실행하며, 이 GPU에 대해 출처가 있는 속도는 Llama 2 7B Q4_0에서 75.6 tok/s(llama.cpp discussion #15013, 커뮤니티 보고, PromptQuorum이 측정한 값 아님) 하나뿐입니다. 32B급 모델은 12GB에 완전히 들어가지 않습니다.**',
