    intro: '**كمبيوتر مزوّد ببطاقة RTX 3060 12GB مستعملة ومعالج Ryzen 5 7600 وذاكرة 32GB DDR5 يشغّل نماذج 7B–14B بتكميم Q4 وتبلغ تكلفته الإجمالية نحو 910 دولارات، أي أقل من 1,000 دولار.** تُعدّ VRAM العامل المحدِّد الرئيسي لاستدلال LLM المحلي، لذا يخصّص هذا التجميع ميزانية GPU لبطاقة بذاكرة 12GB بسعر مستعمل يقارب 300 دولار (من [متتبع InsiderLLM](https://insiderllm.com/guides/nvidia-gpu-prices-rising/)، تاريخ تحديث المصدر 2026-10-15) ويُبقي بقية القطع متواضعة. نموذج 14B بتكميم Q4 (نحو 9-10GB) يتسع في 12GB، أما نماذج فئة 32B فلا تتسع بالكامل وتحتاج إلى تفريغ جزئي إلى CPU، وهو أبطأ بكثير. يسرد هذا الدليل المكوّنات بدقة، وسبب اختيار كل منها على البدائل، وأي أرقام للسرعة لها مصدر. بقية القطع تقديرات خاصة بهذه الصفحة، والإجمالي صحيح فقط مع بطاقة مستعملة: بطاقة RTX 3060 12GB جديدة مُدرجة بنحو 450 دولاراً على [gpuprix](https://gpuprix.com/us/gpus/geforce-rtx-3060-12gb) (2026-11-18) سترفع الإجمالي إلى نحو 1,060 دولار.',
