    leadAnswerBlock: '**يتمحور تجميع كمبيوتر LLM محلي بأقل من 1,000 دولار حول قطعة واحدة: GPU تُختار حسب VRAM لكل دولار. بطاقة RTX 3060 12GB مستعملة (نحو 300 دولار، متتبع InsiderLLM) مع Ryzen 5 7600 (180 دولاراً) وذاكرة 32GB DDR5-6000 (90 دولاراً) وSSD من نوع NVMe Gen4 بسعة 1TB (70 دولاراً) ولوحة أم B650 mATX (130 دولاراً) ومزوّد طاقة 650W 80+ Gold (75 دولاراً) وصندوق mATX (65 دولاراً) يبلغ إجماليها نحو 910 دولارات. يشغّل نماذج 7B-14B بتكميم Q4؛ والسرعة الوحيدة ذات المصدر لهذه GPU هي 75.6 tok/s على Llama 2 7B Q4_0 (نقاش llama.cpp رقم 15013، أبلغ عنها المجتمع ولم تقِسها PromptQuorum). نماذج فئة 32B لا تتسع بالكامل في 12GB.**',
