    intro: '**一台搭载二手RTX 3060 12GB、Ryzen 5 7600和32GB DDR5内存的PC，可在Q4下运行7B-14B模型，总价约$910，低于$1,000。**显存是本地LLM推理的主要限制因素，因此本构建把GPU预算花在一张二手价约$300的12GB显存显卡上（来自[InsiderLLM价格追踪页](https://insiderllm.com/guides/nvidia-gpu-prices-rising/)，来源更新于2026-10-15），其余配件则保持精简。Q4下的14B模型（约9-10GB）可放入12GB；32B级模型无法完全放入，需要部分卸载到CPU，速度会慢得多。本指南列出具体配件、每项选择优于其他方案的原因，以及哪些速度数据有来源。其余配件为本页自行估算的价格，且总价仅在购买二手显卡时成立：2026-11-18在[gpuprix](https://gpuprix.com/us/gpus/geforce-rtx-3060-12gb)上标价约$450的全新RTX 3060 12GB会使总价升至约$1,060。',
