    leadAnswerBlock: '**$1,000以下的本地LLM PC构建的核心只有一个部件：按每美元显存挑选的GPU。二手RTX 3060 12GB（约$300，InsiderLLM价格追踪页）搭配Ryzen 5 7600（$180）、32GB DDR5-6000（$90）、1TB Gen4 NVMe SSD（$70）、B650 mATX主板（$130）、650W 80+ Gold电源（$75）和mATX机箱（$65），总计约$910。可在Q4下运行7B-14B模型；这块GPU唯一有来源的速度是Llama 2 7B Q4_0下75.6 tok/s（llama.cpp讨论#15013，社区上报，非PromptQuorum实测）。32B级模型无法完全放入12GB。**',
