          '**総ビルド費用：約$910。**中古RTX 3060 12GB（約$300）、Ryzen 5 7600（$180）、32GB DDR5-6000（$90）、1TB Gen4 NVMe（$70）、B650 mATXマザーボード（$130）、650W 80+ Gold電源（$75）、mATXケース（$65）。GPU価格は[InsiderLLMトラッカー](https://insiderllm.com/guides/nvidia-gpu-prices-rising/)（中古、情報源の更新日2026-10-15）によるもので、他のパーツは本ページ独自の見積もりです。新品のRTX 3060 12GB（2026-11-18時点でgpuprixに約$450）を選ぶと、総額は約$1,060になります。',
