    designSkin: 'hub',
    theme: 'Hardware Setups',
    title: 'Lokaler LLM-PC-Build unter 1.000 $ mit gebrauchter GPU (2026)',
    heroImage: '/images/local-llm-pc-build-1000-overview-hero-de.webp',
    seoTitle: 'Lokaler LLM-PC-Build unter 1.000 $ mit gebrauchter GPU (2026)',
    intro: '**Ein PC mit gebrauchter RTX 3060 12GB, Ryzen 5 7600 und 32GB DDR5-RAM führt 7B–14B-Modelle bei Q4 aus und kostet zusammen ca. 910 $, also unter 1.000 $ (US-Preise; in Deutschland vermutlich höher).** VRAM ist der wichtigste limitierende Faktor für lokale LLM-Inferenz, daher fließt das GPU-Budget dieses Builds in eine Karte mit 12 GB VRAM zum Gebrauchtpreis von ca. 300 $ (laut [InsiderLLM-Tracker](https://insiderllm.com/guides/nvidia-gpu-prices-rising/), Quelle aktualisiert am 2026-10-15); die übrigen Teile bleiben bewusst bescheiden. Ein 14B-Modell bei Q4 (ca. 9–10 GB) passt in 12 GB; Modelle der 32B-Klasse passen nicht vollständig hinein und müssen teilweise auf die CPU ausgelagert werden, was deutlich langsamer ist. Dieser Leitfaden listet die genauen Komponenten, begründet jede Wahl gegenüber den Alternativen und nennt, welche Geschwindigkeitsangaben belegt sind. Die übrigen Teile sind eigene Schätzungen dieser Seite, und die Summe gilt nur für eine gebrauchte Karte: Eine neue RTX 3060 12GB, bei [gpuprix](https://gpuprix.com/us/gpus/geforce-rtx-3060-12gb) mit ca. 450 $ gelistet (2026-11-18), würde sie auf ca. 1.060 $ erhöhen.',
    metaDescription: 'Lokaler LLM-PC-Build unter 1.000 $ (ca. 910 $, US-Preise): gebrauchte RTX 3060 12GB, Ryzen 5 7600, 32GB DDR5. Läuft mit 7B–14B bei Q4. Teileliste 2026.',
