    targetKeywords: ['lokaler llm pc build 1000 dollar', 'budget pc für lokale llm', 'rtx 3060 12gb llm build', 'günstiger lokaler ki pc 2026', 'lokaler llm build teileliste'],
    leadAnswerBlock: '**Ein lokaler LLM-PC unter 1.000 $ konzentriert sich auf eine Komponente: die GPU, gewählt nach VRAM pro Dollar. Eine gebrauchte RTX 3060 12GB (ca. 300 $, InsiderLLM-Tracker) kombiniert mit einem Ryzen 5 7600 (180 $), 32GB DDR5-6000 (90 $), einer 1TB-Gen4-NVMe-SSD (70 $), einem B650-mATX-Board (130 $), einem 650W-80+-Gold-Netzteil (75 $) und einem mATX-Gehäuse (65 $) ergibt insgesamt ca. 910 $ (US-Preise; in Deutschland vermutlich höher). Er führt 7B–14B-Modelle bei Q4 aus; die einzige belegte Geschwindigkeit für diese GPU sind 75,6 Tok/s mit Llama 2 7B Q4_0 (llama.cpp-Diskussion #15013, von der Community gemeldet, nicht von PromptQuorum gemessen). Modelle der 32B-Klasse passen nicht vollständig in 12 GB.**',
