    intro: '**Un PC avec une RTX 3060 12 Go d\'occasion, un Ryzen 5 7600 et 32 Go de RAM DDR5 fait tourner les modèles 7B–14B en Q4 pour environ $910 au total, soit moins de $1,000.** La VRAM est le principal facteur limitant de l\'inférence LLM locale ; cette configuration consacre donc son budget GPU à une carte de 12 Go de VRAM à un prix d\'occasion d\'environ $300 (d\'après le [suivi d\'InsiderLLM](https://insiderllm.com/guides/nvidia-gpu-prices-rising/), source mise à jour le 2026-10-15) et garde des autres pièces modestes. Un modèle 14B en Q4 (environ 9-10 Go) tient dans 12 Go ; les modèles de classe 32B ne tiennent pas entièrement et nécessitent un déport partiel sur le CPU, nettement plus lent. Ce guide détaille les composants exacts, pourquoi chacun a été choisi plutôt que les alternatives, et quelles vitesses sont sourcées. Les autres pièces sont des estimations propres à cette page, et le total ne vaut que pour une carte d\'occasion : une RTX 3060 12 Go neuve, listée à environ $450 sur [gpuprix](https://gpuprix.com/us/gpus/geforce-rtx-3060-12gb) (2026-11-18), le porterait à environ $1,060.',
