    leadAnswerBlock: '**Une configuration PC pour LLM local à moins de $1,000 repose sur un seul composant : le GPU, choisi pour sa VRAM par dollar. Une RTX 3060 12 Go d\'occasion (environ $300, suivi d\'InsiderLLM) associée à un Ryzen 5 7600 ($180), 32 Go de DDR5-6000 ($90), un SSD NVMe Gen4 de 1 To ($70), une carte mère B650 mATX ($130), une alimentation 650W 80+ Gold ($75) et un boîtier mATX ($65) totalise environ $910. Elle exécute les modèles 7B–14B en Q4 ; la seule vitesse sourcée pour ce GPU est de 75.6 tok/s sur Llama 2 7B Q4_0 (discussion llama.cpp #15013, rapportée par la communauté, non mesurée par PromptQuorum). Les modèles de classe 32B ne tiennent pas entièrement dans 12 Go.**',
