    seoTitle: 'Build de PC para LLM local por menos de $1.000 com GPU usada (2026)',
    intro: '**Um PC com uma RTX 3060 12GB usada, um Ryzen 5 7600 e 32GB de RAM DDR5 executa modelos de 7B a 14B em Q4 e soma cerca de $910, menos de $1.000.** A VRAM é o principal fator limitante da inferência de LLM local, então este build destina seu orçamento de GPU a uma placa com 12GB de VRAM a um preço de usada de cerca de $300 (do [rastreador da InsiderLLM](https://insiderllm.com/guides/nvidia-gpu-prices-rising/), fonte atualizada em 2026-10-15) e mantém as demais peças modestas. Um modelo de 14B em Q4 (cerca de 9-10GB) cabe em 12GB; modelos da classe 32B não cabem por completo e exigem descarregar camadas para a CPU, o que é muito mais lento. Este guia lista os componentes exatos, por que cada um foi escolhido em vez das alternativas e quais números de velocidade têm fonte. As demais peças são estimativas próprias desta página, e o total só vale para uma placa usada: uma RTX 3060 12GB nova, listada a cerca de $450 no [gpuprix](https://gpuprix.com/us/gpus/geforce-rtx-3060-12gb) (2026-11-18), levaria o total a cerca de $1.060. Os preços são dos EUA; no Brasil os valores podem variar bastante devido a impostos de importação.',
