    leadAnswerBlock: '**Um build de PC para LLM local por menos de $1.000 gira em torno de uma peça: a GPU, escolhida por VRAM por dólar. Uma RTX 3060 12GB usada (cerca de $300, rastreador da InsiderLLM) combinada com um Ryzen 5 7600 ($180), 32GB de DDR5-6000 ($90), um SSD NVMe Gen4 de 1TB ($70), uma placa-mãe B650 mATX ($130), uma fonte 650W 80+ Gold ($75) e um gabinete mATX ($65) soma cerca de $910. Ele roda modelos de 7B a 14B em Q4; a única velocidade com fonte para esta GPU é 75.6 tok/s com Llama 2 7B Q4_0 (discussão #15013 do llama.cpp, reportada pela comunidade, não medida pela PromptQuorum). Modelos da classe 32B não cabem por completo em 12GB.**',
