        title: 'O Que Este Orçamento Realmente Compra',
        content: [
          '**A velocidade de inferência de um LLM local é limitada primeiro pela capacidade de VRAM, depois pela largura de banda de memória e, bem distante, pelo poder de computação (núcleos CUDA).** Um modelo que não cabe na VRAM não carrega ou transborda para a RAM do sistema, reduzindo o desempenho em 5 a 10 vezes. Com $1.000, a alocação mais eficaz é colocar a GPU em primeiro lugar e manter todo o resto modesto — por isso a CPU aqui é uma peça de nível médio de $180, e não um topo de linha de $350.',
          'Este build pressupõe inferência de modelo único (um modelo carregado por vez via Ollama, LM Studio ou llama.cpp), não atendimento concorrente multiusuário. Para atender múltiplas requisições simultâneas, os requisitos de VRAM aumentam ainda mais e um orçamento de $1.000 não é realista.',
        ],
